import{_ as e,o,c as a,a2 as r}from"./chunks/framework.CZqXuAiL.js";const p=JSON.parse(`{"title":"For Server Owners — Using Your Firewall","description":"Plain-language guide to Firewall-Plus for game server owners. No networking knowledge needed — enable it, pick your game, and you're protected.","frontmatter":{"title":"For Server Owners — Using Your Firewall","description":"Plain-language guide to Firewall-Plus for game server owners. No networking knowledge needed — enable it, pick your game, and you're protected."},"headers":[],"relativePath":"firewall-plus/fwp-aside/user-guide/for-server-owners.md","filePath":"firewall-plus/fwp-aside/user-guide/for-server-owners.md","lastUpdated":null}`),s={name:"firewall-plus/fwp-aside/user-guide/for-server-owners.md"};function n(i,t,l,d,h,u){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="for-server-owners-—-using-your-firewall" tabindex="-1">For Server Owners — Using Your Firewall <a class="header-anchor" href="#for-server-owners-—-using-your-firewall" aria-label="Permalink to &quot;For Server Owners — Using Your Firewall&quot;">​</a></h1><p>This guide is for <strong>you</strong>, the server owner. No networking knowledge needed. Your host has already done the hard part — you just turn it on.</p><h2 id="what-does-this-thing-actually-do" tabindex="-1">What does this thing actually do? <a class="header-anchor" href="#what-does-this-thing-actually-do" aria-label="Permalink to &quot;What does this thing actually do?&quot;">​</a></h2><p>Firewall-Plus puts a bouncer in front of your game server. It watches the traffic coming into <strong>your server&#39;s ports</strong> (and only yours) and can:</p><ul><li><strong>Slow down or block floods</strong> — when someone tries to knock your server offline with junk traffic (a &quot;DDoS attack&quot;), it limits how fast packets can arrive</li><li><strong>Block troublemakers</strong> — ban specific IP addresses from connecting (blacklist)</li><li><strong>Roll out the red carpet</strong> — always allow your own IP or your friends&#39; IPs (whitelist)</li><li><strong>Protect you automatically</strong> — with SMART mode, it notices an attack by itself and starts blocking it, then emails you about it</li></ul><div class="info custom-block"><p class="custom-block-title">Good to know</p><p>Your firewall <strong>cannot</strong> break anything outside your server. It only touches your assigned game port(s) — never the host&#39;s SSH, panel, or other customers&#39; servers.</p></div><h2 id="first-time-setup-about-2-minutes" tabindex="-1">First-time setup (about 2 minutes) <a class="header-anchor" href="#first-time-setup-about-2-minutes" aria-label="Permalink to &quot;First-time setup (about 2 minutes)&quot;">​</a></h2><p>You only do this once.</p><h3 id="_1-open-the-firewall-tab" tabindex="-1">1. Open the Firewall tab <a class="header-anchor" href="#_1-open-the-firewall-tab" aria-label="Permalink to &quot;1. Open the Firewall tab&quot;">​</a></h3><p>Open your server in the panel and click <strong>Firewall</strong> in the menu.</p><h3 id="_2-turn-it-on" tabindex="-1">2. Turn it on <a class="header-anchor" href="#_2-turn-it-on" aria-label="Permalink to &quot;2. Turn it on&quot;">​</a></h3><p>Go to the <strong>Settings</strong> tab (the sliders icon) and switch on <strong>&quot;Enable Firewall-Plus for this server&quot;</strong>.</p><p>If you see a Terms of Service box, read it and click <strong>I accept</strong> — your host requires this before you can change anything.</p><h3 id="_3-pick-your-game-the-easy-button" tabindex="-1">3. Pick your game (the easy button) <a class="header-anchor" href="#_3-pick-your-game-the-easy-button" aria-label="Permalink to &quot;3. Pick your game (the easy button)&quot;">​</a></h3><p>Open the <strong>Rules</strong> tab and click <strong>Presets</strong>. Choose the preset for your game (Minecraft, Rust, CS2, ARK, Palworld, Valheim…) and apply it. The preset adds a sensible set of protections tuned for that game — you&#39;re done configuring.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Not sure which rules you need? Just use the preset. You can always tweak individual rules later.</p></div><h3 id="_4-apply" tabindex="-1">4. Apply <a class="header-anchor" href="#_4-apply" aria-label="Permalink to &quot;4. Apply&quot;">​</a></h3><p>Click <strong>Apply firewall</strong>. The rules are sent to the machine your server runs on and start working within seconds. The status line in Settings will show <strong>&quot;In sync with node&quot;</strong> when it&#39;s live.</p><h2 id="everyday-things-you-ll-want-to-do" tabindex="-1">Everyday things you&#39;ll want to do <a class="header-anchor" href="#everyday-things-you-ll-want-to-do" aria-label="Permalink to &quot;Everyday things you&#39;ll want to do&quot;">​</a></h2><h3 id="block-someone-blacklist" tabindex="-1">Block someone (blacklist) <a class="header-anchor" href="#block-someone-blacklist" aria-label="Permalink to &quot;Block someone (blacklist)&quot;">​</a></h3><p><strong>Rules → Blacklist → Add entry</strong>, paste their IP address (e.g. <code>203.0.113.50</code>), save. They can no longer reach your server. You can also block a whole range like <code>203.0.113.0/24</code>.</p><p>You can set an expiry so the ban lifts itself automatically.</p><h3 id="always-allow-yourself-or-a-friend-whitelist" tabindex="-1">Always allow yourself or a friend (whitelist) <a class="header-anchor" href="#always-allow-yourself-or-a-friend-whitelist" aria-label="Permalink to &quot;Always allow yourself or a friend (whitelist)&quot;">​</a></h3><p><strong>Rules → Whitelist → Add entry</strong>, add the IP. Whitelisted IPs skip the rate limits — useful for your own connection so you never get caught by your own protections.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Whitelist only IPs you trust. A whitelisted IP bypasses your flood protections (on your ports only).</p></div><h3 id="slow-down-connection-spam" tabindex="-1">Slow down connection spam <a class="header-anchor" href="#slow-down-connection-spam" aria-label="Permalink to &quot;Slow down connection spam&quot;">​</a></h3><p>The preset already includes these, but the useful ones in plain terms:</p><table tabindex="0"><thead><tr><th>Rule</th><th>What it does in plain English</th></tr></thead><tbody><tr><td>SYN limit</td><td>Stops &quot;fake connection&quot; floods — the most common attack on game servers</td></tr><tr><td>Connection limit</td><td>One IP can&#39;t hold more than X connections to your server at once</td></tr><tr><td>New connection rate</td><td>Limits how fast new players (or bots) can connect per second</td></tr><tr><td>UDP limit</td><td>Slows UDP floods — important for games that use UDP (Minecraft Bedrock, Rust, Source games)</td></tr></tbody></table><h3 id="check-what-s-happening" tabindex="-1">Check what&#39;s happening <a class="header-anchor" href="#check-what-s-happening" aria-label="Permalink to &quot;Check what&#39;s happening&quot;">​</a></h3><p>The <strong>Dashboard</strong> tab shows live graphs: packets per second, bandwidth, top talking IPs, and which rules are blocking the most traffic. During an attack you&#39;ll see the spike here.</p><h3 id="look-at-the-logs" tabindex="-1">Look at the logs <a class="header-anchor" href="#look-at-the-logs" aria-label="Permalink to &quot;Look at the logs&quot;">​</a></h3><p>The <strong>Logs</strong> tab shows what the firewall did and when — rules applied, attacks detected, bans added.</p><h2 id="when-you-get-attacked" tabindex="-1">When you get attacked <a class="header-anchor" href="#when-you-get-attacked" aria-label="Permalink to &quot;When you get attacked&quot;">​</a></h2><p>If SMART protection is on (your host may need to enable it for your server):</p><ol><li><strong>It handles the attack automatically</strong> — traffic gets throttled or dropped in escalating steps until the flood stops</li><li><strong>You get an email</strong> — &quot;attack detected&quot; when it starts and &quot;all clear&quot; when it&#39;s over (one email per 5 minutes max, so no spam)</li><li><strong>You see a red banner</strong> on your Firewall dashboard — click <strong>Ack all</strong> to mark events as seen</li></ol><div class="tip custom-block"><p class="custom-block-title">Get alerts in Discord too</p><p>In the <strong>SMART</strong> tab you can paste a Discord webhook URL and pick which events you want posted to your Discord. If SMART is on and you haven&#39;t set this up, the panel will nudge you with a &quot;Get attack alerts&quot; hint.</p></div><h2 id="common-questions" tabindex="-1">Common questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common questions&quot;">​</a></h2><p><strong>Will this increase my ping?</strong> No measurable difference. The rules run inside the host&#39;s network card path and are designed for game traffic.</p><p><strong>Can I lock myself out of my server?</strong> No. The firewall only watches your game port — it can&#39;t touch the panel, console, or SFTP. If you misconfigure something, just disable the rule (or the whole firewall) from the same tab.</p><p><strong>Do I need to re-apply after changing rules?</strong> The panel queues changes automatically in most cases. If you see &quot;Out of sync with node&quot;, just click <strong>Apply firewall</strong>.</p><p><strong>My rules disappeared after my server moved to another node.</strong> That&#39;s normal — the firewall detects the move, cleans up the old machine, and re-applies your rules to the new one automatically.</p><p><strong>What can&#39;t it do?</strong> It protects the network path to your server. It can&#39;t fix a laggy plugin, a full CPU, or an attacker who knows your players&#39; passwords — keep your server software updated too.</p><h2 id="quick-reference" tabindex="-1">Quick reference <a class="header-anchor" href="#quick-reference" aria-label="Permalink to &quot;Quick reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want to…</th><th>Go to</th></tr></thead><tbody><tr><td>Turn the firewall on/off</td><td><strong>Settings</strong> tab</td></tr><tr><td>Add or edit protections</td><td><strong>Rules</strong> tab (or <strong>Presets</strong>)</td></tr><tr><td>Ban an IP</td><td><strong>Rules → Blacklist</strong></td></tr><tr><td>Always allow an IP</td><td><strong>Rules → Whitelist</strong></td></tr><tr><td>See live traffic graphs</td><td><strong>Dashboard</strong> tab</td></tr><tr><td>See what happened earlier</td><td><strong>Logs</strong> tab</td></tr><tr><td>Set up Discord attack alerts</td><td><strong>Rules → SMART</strong></td></tr><tr><td>Save/restore your config</td><td><strong>Settings</strong> (import/export)</td></tr></tbody></table>',44)])])}const g=e(s,[["render",n]]);export{p as __pageData,g as default};
